// ============================================
// VALIDATION INPUT - RAG Process Source
// ============================================

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

const errors = [];

// --- Required fields ---
const action = body.action;
const sourceId = body.source_id;
const tenantId = body.tenant_id || headers['x-tenant-id'] || headers['X-Tenant-ID'];
const guildId = body.guild_id;
const botId = body.bot_id;
const fileType = body.file_type;

// Backend API config
const backendApiUrl = body.backend_api_url;
const backendServiceToken = body.backend_service_token;

// Validate required
if (!action) errors.push('action requis');
else if (!['process', 'retry'].includes(action)) errors.push('action doit etre process ou retry');

if (!sourceId) errors.push('source_id requis');
if (!tenantId) errors.push('tenant_id requis');
if (!guildId) errors.push('guild_id requis');
if (!botId) errors.push('bot_id requis');
if (!fileType) errors.push('file_type requis');
if (!backendApiUrl) errors.push('backend_api_url requis');
if (!backendServiceToken) errors.push('backend_service_token requis');

// File source (b2_file_key for uploads, url for links)
const b2FileKey = body.b2_file_key || null;
const url = body.url || null;
const extractionMode = body.extraction_mode || null;

if (fileType === 'yt' && !url) {
  errors.push('url requis pour file_type yt');
}
if (['pdf', 'txt', 'md', 'docx', 'xlsx', 'pptx', 'mp4', 'mp3'].includes(fileType) && !b2FileKey && !url) {
  errors.push('b2_file_key ou url requis');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    source_id: sourceId
  };
}

// Determine extraction method based on file_type
let extractionMethod;
switch (fileType) {
  case 'pdf': extractionMethod = 'pdfplumber'; break;
  case 'txt': case 'md': extractionMethod = 'raw_text'; break;
  case 'docx': extractionMethod = 'docx_text'; break;
  case 'xlsx': extractionMethod = 'xlsx_tabular'; break;
  case 'pptx': extractionMethod = 'pptx_slides'; break;
  case 'mp4': case 'mp3': extractionMethod = 'whisper'; break;
  case 'yt': extractionMethod = extractionMode || 'subtitles'; break;
  default: extractionMethod = 'unknown';
}

return {
  valid: true,
  action: action,
  source_id: sourceId,
  tenant_id: tenantId,
  guild_id: guildId,
  bot_id: botId,
  file_type: fileType,
  b2_file_key: b2FileKey,
  url: url,
  extraction_mode: extractionMode,
  extraction_method: extractionMethod,
  backend_api_url: backendApiUrl,
  backend_service_token: backendServiceToken,
  start_time: Date.now()
};

