// ============================================
// CHUNKING - Split text into chunks
// ============================================

const ctx = $('Merge Extraction').item.json;
const text = ctx.extracted_text || '';

// Simple chunking strategy: split by paragraphs, then combine to target size
const CHUNK_SIZE = 1000; // characters
const CHUNK_OVERLAP = 200; // overlap between chunks

const chunks = [];
let currentChunk = '';
let chunkIndex = 0;

// Split by double newlines (paragraphs)
const paragraphs = text.split(/\n\n+/);

for (const para of paragraphs) {
  if (currentChunk.length + para.length > CHUNK_SIZE && currentChunk.length > 0) {
    // Save current chunk
    chunks.push({
      index: chunkIndex,
      text: currentChunk.trim(),
      char_count: currentChunk.trim().length
    });
    chunkIndex++;

    // Start new chunk with overlap
    const words = currentChunk.split(' ');
    const overlapWords = words.slice(-Math.ceil(CHUNK_OVERLAP / 5)); // Approximate words for overlap
    currentChunk = overlapWords.join(' ') + '\n\n' + para;
  } else {
    currentChunk += (currentChunk ? '\n\n' : '') + para;
  }
}

// Don't forget the last chunk
if (currentChunk.trim()) {
  chunks.push({
    index: chunkIndex,
    text: currentChunk.trim(),
    char_count: currentChunk.trim().length
  });
}

return {
  ...ctx,
  chunks: chunks,
  chunk_count: chunks.length
};

